{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "장치를 준비하고 소리를 입력한 뒤 진동 변환과 홈 기록을 수행하는 절차의 순서이므로 과정 관계이다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "나팔에 입력한 소리가 실제로 나팔의 진동을 일으키므로 인과·작용 관계이다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "나팔의 진동이 바늘에 전달되어 그 형태에 따른 홈을 만들게 하므로 실제 작용 관계이다."
    },
    {
      "id": "R4",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "소리의 진동을 판의 홈으로 기록하는 방식을 아날로그 저장이라고 규정하므로 정의·명명 관계이다."
    },
    {
      "id": "R5",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "초기 녹음기에서 이후에 등장한 매체로 시대적 설명 범위를 옮기므로 전개 관계이다."
    },
    {
      "id": "R6",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "과거의 아날로그 기록에서 현재의 디지털 파일 저장으로 시대와 논의를 전환한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "균일한 비트 할당을 일반적으로 사용하는 16비트라는 구체적 수치로 풀어 설명한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "16비트를 할당한다는 설명을 그 이진수 값으로 소리 크기를 구분한다는 세부 방식으로 구체화한다."
    },
    {
      "id": "R9",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "디지털 소리의 표현 방식과 음질에서 데이터 용량과 압축 필요성으로 논의의 초점이 옮겨 간다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "데이터 양이 많다는 사실을 압축이 필요하다는 당위적 판단의 이유로 제시하므로 근거 관계이다."
    },
    {
      "id": "R11",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "오디오 압축이 필요하다는 과제에 대응하는 실제 기술로 지각부호화를 제시한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "열거한 청각 특성 중 최소가청강도의 뜻과 주파수별 특성을 자세히 설명한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 최소 크기라는 정의에서 그보다 큰 소리는 들린다는 판단을 도출한다."
    },
    {
      "id": "R14",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 최소 크기라는 정의에서 그보다 작은 소리는 들리지 않는다는 판단이 따라 나온다."
    },
    {
      "id": "R15",
      "type": "CONDITION",
      "otherName": "",
      "reason": "소리 크기가 최소가청강도보다 큰지 작은지에 따라 가청 여부가 갈리므로 조건·분기 관계이다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수별로 최소가청강도가 정해진다는 설명을 특정 주파수 구간의 사례로 보여 준다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수별 최소가청강도의 차이를 100 Hz 이하 저음의 사례로 구체화한다."
    },
    {
      "id": "R18",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 주파수 구간을 소리가 들리기 위해 필요한 크기라는 같은 기준에서 비교하여 차이를 보인다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 열거한 청각 특성 중 차폐가 어떤 현상인지 자세히 풀어 설명한다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "차폐음이라는 큰 소리가 작은 소리를 들리지 않게 하는 차폐 현상을 실제로 일으킨다."
    },
    {
      "id": "R21",
      "type": "CONDITION",
      "otherName": "",
      "reason": "두 소리의 주파수가 가까운지 충분히 떨어져 있는지에 따라 차폐 발생 여부가 갈린다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "임계대역의 정의에 이어 그 폭이 차폐음의 주파수에 따라 달라진다는 세부 성질을 설명한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수에 따라 임계대역 폭이 다르다는 설명을 고음과 저음의 폭 비교로 구체화한다."
    },
    {
      "id": "R24",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "최소 감지 크기를 나타내는 두 개념을 조용한 상태와 차폐를 고려한 상태라는 기준에서 구별한다."
    },
    {
      "id": "R25",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "차폐와 임계대역에 관한 청각 원리를 오디오 신호 압축이라는 기술 영역에 가져다 쓴다."
    },
    {
      "id": "R26",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "실제 감지 한계를 나타내는 차폐 문턱값의 원리를 오디오 신호 압축에 활용한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각 특성을 이용해 압축한다는 설명을 대역 분할과 문턱값 산출 및 비트 할당의 구체적 절차로 풀어 준다."
    },
    {
      "id": "R28",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 정의한 차폐 가능 주파수 구간을 실제 오디오 신호의 분할 단위로 적용한다."
    },
    {
      "id": "R29",
      "type": "PROCESS",
      "otherName": "",
      "reason": "오디오 신호를 임계대역으로 나눈 결과를 바탕으로 각 대역의 문턱값을 구하는 다음 단계가 진행된다."
    },
    {
      "id": "R30",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "주파수별 최소가청강도라는 청각 원리를 지각부호화의 대역별 문턱값 계산에 적용한다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "큰 소리가 차폐를 일으킨다는 특성을 지각부호화의 차폐 문턱값 계산에 활용한다."
    },
    {
      "id": "R32",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 산출한 차폐 문턱값을 바탕으로 소리별 비트 수를 정하는 다음 처리 단계가 이어진다."
    },
    {
      "id": "R33",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "차폐 문턱값이 실제 감지 가능한 최소 크기라는 정의에서 그보다 작은 소리는 들리지 않는다는 판단을 도출한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "문턱값보다 작은 소리가 들리지 않는다는 사실이 해당 소리를 제거하는 처리의 이유로 제시된다."
    },
    {
      "id": "R35",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "비트 차등 할당과 불가청 소리 제거를 통한 압축 방식을 품질 저하를 최소화하는 기술로 종합하여 재진술한다."
    },
    {
      "id": "R36",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "일반 오디오 파일과 지각부호화를 비트 할당 방식이라는 같은 기준에서 균일 할당과 차등 할당으로 대비한다."
    },
    {
      "id": "R37",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "감도가 낮은 소리를 제거한다는 일반적 설명을 차폐 문턱값보다 작은 소리의 제거로 구체화한다."
    }
  ]
}

